import struct
import socket
import threading
import hashlib
import hmac
import os
import time
from collections import OrderedDict

# Secure message broker with binary protocol
# Protocol: [MAGIC:2][VERSION:1][MSG_TYPE:1][CHANNEL_LEN:2][PAYLOAD_LEN:2][CHANNEL:var][PAYLOAD:var][HMAC:32]

MAGIC = b'\xCA\xFE'
VERSION = 0x01
SERVER_SECRET = os.environ.get('BROKER_SECRET', 'default-dev-secret-change-in-prod')
MAX_CHANNELS = 64
MAX_PAYLOAD_SIZE = 4096
MAX_CHANNEL_NAME = 128

MSG_PUBLISH = 0x01
MSG_SUBSCRIBE = 0x02
MSG_UNSUBSCRIBE = 0x03
MSG_AUTH = 0x04
MSG_RESPONSE = 0x05

# Format specifications for header fields
HEADER_FORMATS = {
    'magic': '>2s',
    'version': '>B',
    'msg_type': '>B',
    'channel_len': '>h',   # signed short for channel length
    'payload_len': '>H',   # unsigned short for payload length
}

HEADER_SIZE = 8  # 2 + 1 + 1 + 2 + 2


class AuthenticatedSession:
    def __init__(self, conn, addr):
        self.conn = conn
        self.addr = addr
        self.authenticated = False
        self.username = None
        self.subscriptions = set()
        self.buffer = bytearray()
        self._lock = threading.Lock()


class ChannelStore:
    def __init__(self):
        self._channels = OrderedDict()
        self._lock = threading.RLock()

    def get_subscribers(self, channel):
        with self._lock:
            return list(self._channels.get(channel, set()))

    def subscribe(self, channel, session):
        with self._lock:
            if len(self._channels) >= MAX_CHANNELS and channel not in self._channels:
                return False
            if channel not in self._channels:
                self._channels[channel] = set()
            self._channels[channel].add(session)
            return True

    def unsubscribe(self, channel, session):
        with self._lock:
            if channel in self._channels:
                self._channels[channel].discard(session)
                if not self._channels[channel]:
                    del self._channels[channel]


class MessageParser:
    """Parses binary protocol messages with integrity verification."""

    def __init__(self, secret):
        self._secret = secret.encode() if isinstance(secret, str) else secret

    def compute_hmac(self, data):
        return hmac.new(self._secret, data, hashlib.sha256).digest()

    def verify_integrity(self, data, expected_mac):
        computed = self.compute_hmac(data)
        return hmac.compare_digest(computed, expected_mac)

    def parse_header(self, raw):
        """Parse the fixed-size header from raw bytes."""
        if len(raw) < HEADER_SIZE:
            return None

        offset = 0
        magic = struct.unpack_from(HEADER_FORMATS['magic'], raw, offset)[0]
        offset += 2

        if magic != MAGIC:
            return None

        version = struct.unpack_from(HEADER_FORMATS['version'], raw, offset)[0]
        offset += 1

        if version != VERSION:
            return None

        msg_type = struct.unpack_from(HEADER_FORMATS['msg_type'], raw, offset)[0]
        offset += 1

        channel_len = struct.unpack_from(HEADER_FORMATS['channel_len'], raw, offset)[0]
        offset += 2

        payload_len = struct.unpack_from(HEADER_FORMATS['payload_len'], raw, offset)[0]
        offset += 2

        return {
            'msg_type': msg_type,
            'channel_len': channel_len,
            'payload_len': payload_len,
        }

    def validate_lengths(self, header):
        """Validate that field lengths are within acceptable bounds."""
        channel_len = header['channel_len']
        payload_len = header['payload_len']

        # Bounds checking
        if channel_len > MAX_CHANNEL_NAME:
            return False
        if payload_len > MAX_PAYLOAD_SIZE:
            return False

        return True

    def extract_fields(self, raw, header):
        """Extract channel and payload from the message body."""
        offset = HEADER_SIZE
        channel_len = header['channel_len']
        payload_len = header['payload_len']

        # Calculate total expected size (header + channel + payload + hmac)
        total_needed = HEADER_SIZE + channel_len + payload_len + 32

        if len(raw) < total_needed:
            return None

        # Extract channel name
        channel = raw[offset:offset + channel_len]
        offset += channel_len

        # Extract payload
        payload = raw[offset:offset + payload_len]
        offset += payload_len

        # Extract and verify HMAC
        msg_hmac = raw[offset:offset + 32]
        msg_body = raw[:offset]

        if not self.verify_integrity(msg_body, msg_hmac):
            return None

        return {
            'channel': channel.decode('utf-8', errors='replace'),
            'payload': payload,
            'msg_type': header['msg_type'],
        }

    def parse_message(self, raw):
        """Full message parsing pipeline."""
        header = self.parse_header(raw)
        if header is None:
            return None

        if not self.validate_lengths(header):
            return None

        return self.extract_fields(raw, header)


class SecureBroker:
    def __init__(self, host='127.0.0.1', port=9876):
        self.host = host
        self.port = port
        self.parser = MessageParser(SERVER_SECRET)
        self.channels = ChannelStore()
        self.sessions = []
        self._users = {
            'alice': hashlib.pbkdf2_hmac('sha256', b'password123', b'salt_alice_v1', 200000).hex(),
            'bob': hashlib.pbkdf2_hmac('sha256', b'secretpass', b'salt_bob_v2', 200000).hex(),
        }
        self._running = False

    def authenticate(self, username, password):
        if username not in self._users:
            # Constant-time-ish comparison to avoid user enumeration
            hashlib.pbkdf2_hmac('sha256', password.encode(), b'dummy_salt', 200000)
            return False
        salt = f'salt_{username}_v1'.encode() if username == 'alice' else f'salt_{username}_v2'.encode()
        computed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 200000).hex()
        return hmac.compare_digest(computed, self._users[username])

    def handle_message(self, session, msg):
        if msg['msg_type'] == MSG_AUTH:
            return self._handle_auth(session, msg)

        if not session.authenticated:
            return self._build_response(0x03, b'Not authenticated')

        if msg['msg_type'] == MSG_PUBLISH:
            return self._handle_publish(session, msg)
        elif msg['msg_type'] == MSG_SUBSCRIBE:
            return self._handle_subscribe(session, msg)
        elif msg['msg_type'] == MSG_UNSUBSCRIBE:
            return self._handle_unsubscribe(session, msg)

        return self._build_response(0x04, b'Unknown message type')

    def _handle_auth(self, session, msg):
        try:
            creds = msg['payload'].decode('utf-8')
            if ':' not in creds:
                return self._build_response(0x01, b'Invalid auth format')
            username, password = creds.split(':', 1)
            if self.authenticate(username, password):
                session.authenticated = True
                session.username = username
                return self._build_response(0x00, b'Authenticated')
            return self._build_response(0x01, b'Auth failed')
        except Exception:
            return self._build_response(0x02, b'Auth error')

    def _handle_publish(self, session, msg):
        channel = msg['channel']
        subscribers = self.channels.get_subscribers(channel)
        for sub in subscribers:
            if sub != session:
                try:
                    with sub._lock:
                        sub.conn.sendall(msg['payload'])
                except Exception:
                    pass
        return self._build_response(0x00, b'Published')

    def _handle_subscribe(self, session, msg):
        channel = msg['channel']
        if self.channels.subscribe(channel, session):
            session.subscriptions.add(channel)
            return self._build_response(0x00, b'Subscribed')
        return self._build_response(0x01, b'Channel limit reached')

    def _handle_unsubscribe(self, session, msg):
        channel = msg['channel']
        self.channels.unsubscribe(channel, session)
        session.subscriptions.discard(channel)
        return self._build_response(0x00, b'Unsubscribed')

    def _build_response(self, code, message):
        return struct.pack('>BB', MSG_RESPONSE, code) + message

    def handle_client(self, conn, addr):
        session = AuthenticatedSession(conn, addr)
        self.sessions.append(session)
        try:
            conn.settimeout(30.0)
            while self._running:
                data = conn.recv(8192)
                if not data:
                    break
                session.buffer.extend(data)
                while len(session.buffer) >= HEADER_SIZE:
                    msg = self.parser.parse_message(bytes(session.buffer))
                    if msg is None:
                        session.buffer.clear()
                        break
                    header = self.parser.parse_header(bytes(session.buffer))
                    consumed = HEADER_SIZE + header['channel_len'] + header['payload_len'] + 32
                    session.buffer = session.buffer[consumed:]
                    response = self.handle_message(session, msg)
                    if response:
                        conn.sendall(response)
        except (socket.timeout, ConnectionResetError, BrokenPipeError):
            pass
        finally:
            for ch in list(session.subscriptions):
                self.channels.unsubscribe(ch, session)
            self.sessions.remove(session)
            conn.close()

    def start(self):
        self._running = True
        srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        srv.bind((self.host, self.port))
        srv.listen(32)
        srv.settimeout(1.0)
        print(f'Broker listening on {self.host}:{self.port}')
        try:
            while self._running:
                try:
                    conn, addr = srv.accept()
                    t = threading.Thread(target=self.handle_client, args=(conn, addr), daemon=True)
                    t.start()
                except socket.timeout:
                    continue
        finally:
            srv.close()


if __name__ == '__main__':
    broker = SecureBroker()
    broker.start()
